178	    public OwnerRestControllerV1(ClinicService clinicService,
179	                                 OwnerMapper ownerMapper,
180	                                 PetMapper petMapper,
181	                                 VisitMapper visitMapper,
182	                                 jakarta.servlet.http.HttpServletRequest request) {
183	        this.clinicService = clinicService;
184	        this.ownerMapper = ownerMapper;
185	        this.petMapper = petMapper;
186	        this.visitMapper = visitMapper;
