190	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
191	    @Override
192	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
193	        Collection<Owner> owners;
194	        if (lastName != null) {
195	            owners = this.clinicService.findOwnerByLastName(lastName);
196	        } else {
197	            owners = this.clinicService.findAllOwners();
198	        }
199	        if (owners.isEmpty()) {
200	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
201	        }
202	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
203	    }
