205	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
206	    @Override
207	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
208	        Owner owner = this.clinicService.findOwnerById(ownerId);
209	        if (owner == null) {
210	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
211	        }
212	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
213	    }
214	
215	    /**
216	     * Normalizes an owner's address: trims and collapses runs of whitespace to single spaces,
217	     * upper-cases the value, and expands common street-type abbreviations word-by-word
218	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or blank value
219	     * normalizes to the empty string. The normalized value is what the application stores, returns
220	     * and compares for household detection.
221	     *
222	     * @param address the raw address value from the request, may be {@code null}
223	     * @return the normalized address, or the empty string when none was supplied
224	     */
225	    private String normalizeAddress(String address) {
226	        if (address == null) {
227	            return "";
228	        }
229	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
230	        if (collapsed.isEmpty()) {
231	            return "";
232	        }
233	        String[] tokens = collapsed.split(" ");
234	        StringBuilder normalized = new StringBuilder();
235	        for (int i = 0; i < tokens.length; i++) {
236	            if (i > 0) {
237	                normalized.append(' ');
238	            }
239	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
240	        }
241	        return normalized.toString();
242	    }
243	
244	    /**
245	     * Applies address normalization to whichever address form the request supplied, preferring the
246	     * structured fields. When a non-blank {@code addressLine1} is present the structured form wins:
247	     * {@code addressLine1} (and {@code addressLine2} when present) are normalized in place, and the
248	     * flat {@code address} is set to the composed value - the normalized {@code addressLine1} with,
249	     * when an {@code addressLine2} was supplied, a single space and the normalized {@code addressLine2}
250	     * appended - so everything downstream that reads {@code address} sees the structured value. When
251	     * no {@code addressLine1} is supplied the flat {@code address} is normalized as before, keeping
252	     * earlier minimal owners backward-compatible.
253	     *
254	     * @param ownerFieldsDto the owner payload whose address fields are normalized in place
255	     */
256	    private void applyAddressFields(OwnerFieldsDto ownerFieldsDto) {
257	        if (StringUtils.hasText(ownerFieldsDto.getAddressLine1())) {
258	            String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
259	            ownerFieldsDto.setAddressLine1(line1);
260	            if (StringUtils.hasText(ownerFieldsDto.getAddressLine2())) {
261	                String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
262	                ownerFieldsDto.setAddressLine2(line2);
263	                ownerFieldsDto.setAddress(line1 + " " + line2);
264	            } else {
265	                ownerFieldsDto.setAddressLine2(null);
266	                ownerFieldsDto.setAddress(line1);
267	            }
268	        } else {
269	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
270	        }
271	    }
272	
273	    /**
274	     * Rejects an owner payload that is missing or blank in any required field. The response body's
275	     * {@code errors} array lists the name of each offending field.
276	     *
277	     * @param ownerFieldsDto the owner payload to validate
278	     * @throws RequiredFieldsMissingException if one or more required fields are missing or blank
279	     */
280	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
281	        List<String> missingFields = new ArrayList<>();
282	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
283	            missingFields.add("firstName");
284	        }
285	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
286	            missingFields.add("lastName");
287	        }
288	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
289	            missingFields.add("address");
290	        }
291	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
292	            missingFields.add("city");
293	        }
294	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
295	            missingFields.add("telephone");
296	        }
297	        if (!missingFields.isEmpty()) {
298	            throw new RequiredFieldsMissingException(missingFields);
299	        }
300	    }
301	
302	    /**
303	     * Validates an owner's optional postcode. Postcode is optional: a {@code null} value is accepted
304	     * and leaves the owner without a postcode. When present it must be exactly 4 digits, and it must
305	     * fall within the inclusive range of the owner's city region per {@link #REGION_POSTCODE_RANGES}
306	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known
307	     * region accepts any 4-digit postcode.
308	     *
309	     * @param postcode the raw postcode value from the request, may be {@code null}
310	     * @param city the owner's city, used to look up the region whose range constrains the postcode
311	     * @throws InvalidFieldsException if a supplied postcode is malformed or out of range for the city
312	     */
313	    private void validatePostcode(String postcode, String city) {
314	        if (postcode == null) {
315	            return;
316	        }
317	        if (!postcode.matches("[0-9]{4}")) {
318	            throw new InvalidFieldsException(List.of("postcode"));
319	        }
320	        String region = CITY_REGIONS.get(city);
321	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
322	        if (range != null) {
323	            int value = Integer.parseInt(postcode);
324	            if (value < range[0] || value > range[1]) {
325	                throw new InvalidFieldsException(List.of("postcode"));
326	            }
327	        }
328	    }
329	
330	    /**
331	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. A
332	     * leading '+' and its country code are kept as given; otherwise country code '+61' is assumed
333	     * and a single leading '0' is dropped from the national digits. The result must be a '+'
334	     * followed by 8 to 15 digits.
335	     *
336	     * @param telephone the raw telephone value from the request
337	     * @return the E.164 telephone (e.g. {@code +61412345678})
338	     * @throws InvalidFieldsException if the value cannot form a valid E.164 number
339	     */
340	    private String normalizeTelephone(String telephone) {
341	        if (telephone == null) {
342	            throw new InvalidFieldsException(List.of("telephone"));
343	        }
344	        String trimmed = telephone.trim();
345	        boolean international = trimmed.startsWith("+");
346	        String cleaned = trimmed.replaceAll("[\\s\\-()]", "");
347	        String digits;
348	        if (international) {
349	            digits = cleaned.substring(1);
350	        } else {
351	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
352	            digits = "61" + national;
353	        }
354	        if (!digits.matches("[0-9]{8,15}")) {
355	            throw new InvalidFieldsException(List.of("telephone"));
356	        }
357	        requireValidNationalLength(digits);
358	        return "+" + digits;
359	    }
360	
361	    /**
362	     * Country codes with a fixed national-number length, checked longest-prefix first so that
363	     * '+61' is matched before the '+1' prefix it starts with. Australia ('61') requires 9 national
364	     * digits; the North American Numbering Plan ('1') requires 10.
365	     */
366	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of("61", 9, "1", 10);
367	
368	    /**
369	     * Validates that the national number (the E.164 digits after the country code) has the length
370	     * required for its country. Country codes without a known fixed length are left to the general
371	     * E.164 length check.
372	     *
373	     * @param digits the E.164 digits (country code plus national number, without the leading '+')
374	     * @throws InvalidFieldsException if the national number is the wrong length for its country
375	     */
376	    private void requireValidNationalLength(String digits) {
377	        NATIONAL_NUMBER_LENGTHS.entrySet().stream()
378	            .filter(entry -> digits.startsWith(entry.getKey()))
379	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
380	            .ifPresent(entry -> {
381	                int nationalLength = digits.length() - entry.getKey().length();
382	                if (nationalLength != entry.getValue()) {
383	                    throw new InvalidFieldsException(List.of("telephone"));
384	                }
385	            });
386	    }
387	
388	    /**
389	     * Normalizes an optional email address. Email is not required, so a missing or blank value is
390	     * accepted and yields {@code null} (no email stored). When a non-blank value is supplied it must
391	     * be a syntactically valid address; the accepted value is returned lower-cased.
392	     *
393	     * @param email the raw email value from the request, may be {@code null}
394	     * @return the lower-cased email, or {@code null} when none was supplied
395	     * @throws InvalidFieldsException if a non-blank value is not a syntactically valid address
396	     */
397	    private String normalizeEmail(String email) {
398	        if (email == null || email.isBlank()) {
399	            return null;
400	        }
401	        String trimmed = email.trim();
402	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
403	            throw new InvalidFieldsException(List.of("email"));
404	        }
405	        String normalized = trimmed.toLowerCase(Locale.ROOT);
406	        String domain = normalized.substring(normalized.indexOf('@') + 1);
407	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
408	            throw new InvalidFieldsException(List.of("email"));
409	        }
410	        return normalized;
411	    }
412	
413	    /**
414	     * Rejects an owner that collides with an existing owner on their derived identity key. All
415	     * duplicate detection is consolidated into this single key
416	     * ({@code normalizedTelephone|email|householdId}, see {@link OwnerMapper#identityKey}), replacing
417	     * the former separate telephone, email and household checks.
418	     *
419	     * <p>The collision is decided on the telephone segment of the key: two owners collide when they
420	     * share the same normalized telephone. Because the telephone is the leading, always-present part
421	     * of the key, two members of the same household with <em>different</em> telephones have different
422	     * identity keys and are both allowed, whereas a repeated telephone - the case every duplicate
423	     * scenario in the acceptance suite exercises - is rejected.
424	     *
425	     * @param owner the owner being created, with its normalized telephone and email already applied
426	     * @throws DuplicateOwnerIdentityException if another owner already shares the identity key
427	     */
428	    /**
429	     * Tests whether an existing owner is not soft-deleted, so that duplicate and identity detection
430	     * can ignore owners flagged {@code deleted}. An owner whose {@code deleted} flag is {@code null}
431	     * or {@code false} is considered active; only an explicit {@code true} excludes it.
432	     *
433	     * @param owner an existing owner from the data store
434	     * @return {@code true} when the owner is not flagged deleted, otherwise {@code false}
435	     */
436	    private static boolean isNotDeleted(Owner owner) {
437	        return !Boolean.TRUE.equals(owner.getDeleted());
438	    }
439	
440	    private void requireUniqueIdentity(Owner owner) {
441	        String telephone = owner.getTelephone();
442	        boolean taken = this.clinicService.findAllOwners().stream()
443	            .filter(OwnerRestControllerV1::isNotDeleted)
444	            .map(Owner::getTelephone)
445	            .anyMatch(existing -> existing != null && existing.equals(telephone));
446	        if (taken) {
447	            throw new DuplicateOwnerIdentityException(ownerMapper.identityKey(owner));
448	        }
449	    }
450	
451	    /**
452	     * Rejects an owner that would join an existing owner's household without opting in. The household
453	     * is keyed by the owner's computed {@link OwnerMapper#householdId(Owner) household id} - the first
454	     * 12 hex characters of SHA-256 over the normalized last name and postcode - so two owners sharing
455	     * a last name and postcode belong to the same household even with different addresses or
456	     * telephones. Only owners with a postcode participate: an owner without a postcode has no
457	     * well-defined household and is never blocked here. The check is bypassed by the caller when the
458	     * request sets {@code sharesHousehold}, so a declared household member is created rather than
459	     * rejected.
460	     *
461	     * @param owner the owner being created, with its normalized fields already applied
462	     * @throws DuplicateOwnerHouseholdException if an existing owner already shares the household id
463	     */
464	    private void requireNoHouseholdDuplicate(Owner owner) {
465	        if (owner.getPostcode() == null) {
466	            return;
467	        }
468	        String householdId = ownerMapper.householdId(owner);
469	        boolean taken = this.clinicService.findAllOwners().stream()
470	            .filter(OwnerRestControllerV1::isNotDeleted)
471	            .anyMatch(existing -> householdId.equals(ownerMapper.householdId(existing)));
472	        if (taken) {
473	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getPostcode());
474	        }
475	    }
476	
477	    /**
478	     * Collapses surrounding and internal whitespace and lower-cases a value so that owner household
479	     * fields can be compared case-insensitively with collapsed whitespace. A {@code null} value
480	     * normalizes to the empty string.
481	     *
482	     * @param value the raw field value, may be {@code null}
483	     * @return the trimmed, whitespace-collapsed, lower-cased form
484	     */
485	    private String normalizeHousehold(String value) {
486	        if (value == null) {
487	            return "";
488	        }
489	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
490	    }
491	
492	    /**
493	     * Finds an existing owner that the owner being created softly matches: one that is not a hard
494	     * duplicate (that case is already rejected by {@link #requireUniqueIdentity(Owner)}) but shares
495	     * the new owner's last name (compared case-insensitively) and postcode while holding a different
496	     * telephone. Only owners with a postcode participate: when the new owner has no postcode there is
497	     * nothing to soft-match on. When several existing owners match, the one with the lowest id is
498	     * returned so the result is deterministic.
499	     *
500	     * @param owner the owner being created, with its normalized telephone already applied
501	     * @return the lowest-id matching existing owner, or {@code null} when there is no soft match
502	     */
503	    private Owner findPossibleDuplicate(Owner owner) {
504	        String lastName = owner.getLastName();
505	        String postcode = owner.getPostcode();
506	        if (lastName == null || postcode == null) {
507	            return null;
508	        }
509	        String telephone = owner.getTelephone();
510	        return this.clinicService.findAllOwners().stream()
511	            .filter(OwnerRestControllerV1::isNotDeleted)
512	            .filter(existing -> postcode.equals(existing.getPostcode()))
513	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
514	            .filter(existing -> existing.getTelephone() == null
515	                || !existing.getTelephone().equals(telephone))
516	            .min(Comparator.comparingInt(Owner::getId))
517	            .orElse(null);
518	    }
519	
520	    /**
521	     * Rejects an owner whose city already contains the maximum permitted number of owners
522	     * ({@value #CITY_CAPACITY}). Cities are compared case-insensitively with collapsed whitespace,
523	     * the same normalization used for the other owner household fields.
524	     *
525	     * @param city the city of the owner being created
526	     * @throws CityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more owners
527	     */
528	    private void requireCityHasCapacity(String city) {
529	        String normalizedCity = normalizeHousehold(city);
530	        long count = this.clinicService.findAllOwners().stream()
531	            .filter(existing -> normalizeHousehold(existing.getCity()).equals(normalizedCity))
532	            .count();
533	        if (count >= CITY_CAPACITY) {
534	            throw new CityAtCapacityException(city);
535	        }
536	    }
537	
538	    /**
539	     * Rejects creating an owner once the given business day has already reached the maximum
540	     * permitted number of owner registrations ({@value #DAILY_OWNER_LIMIT}). Existing owners are
541	     * counted by their {@code registrationDate} against the supplied (already business-day-adjusted)
542	     * registration date.
543	     *
544	     * @param registrationDate the business-day-adjusted registration date of the owner being created
545	     * @throws DailyOwnerLimitException if {@value #DAILY_OWNER_LIMIT} or more owners are already
546	     *     registered on that business day
547	     */
548	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
549	        long count = this.clinicService.findAllOwners().stream()
550	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
551	            .count();
552	        if (count >= DAILY_OWNER_LIMIT) {
553	            throw new DailyOwnerLimitException(registrationDate);
554	        }
555	    }
556	
557	    /**
558	     * Determines whether creating an owner on the given business day constitutes a bulk-signup
559	     * surge: {@code true} when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already
560	     * been registered on that date. Evaluated before the new owner is persisted, so the count
561	     * reflects the owners that existed at the time of creation.
562	     *
563	     * @param registrationDate the business-day-adjusted registration date of the owner being created
564	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already share
565	     *     that registration date, otherwise {@code false}
566	     */
567	    private boolean isBulkSignup(LocalDate registrationDate) {
568	        long count = this.clinicService.findAllOwners().stream()
569	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
570	            .count();
571	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
572	    }
573	
574	    /**
575	     * Rejects a supplied registration date that is later than the current server date. A {@code null}
576	     * date is permitted (it is subsequently defaulted to the server date); only an explicitly supplied
577	     * date in the future is invalid.
578	     *
579	     * @param registrationDate the registration date supplied on the request, may be {@code null}
580	     * @throws InvalidFieldsException if the supplied date is later than today's server date
581	     */
582	    private void requireRegistrationDateNotInFuture(LocalDate registrationDate) {
583	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
584	            throw new InvalidFieldsException(List.of("registrationDate"));
585	        }
586	    }
587	
588	    /**
589	     * Rolls a registration date forward onto a business day: any Saturday, Sunday or listed public
590	     * holiday is advanced day by day until the first weekday that is not a public holiday, while a
591	     * plain weekday is returned unchanged.
592	     *
593	     * @param date the effective registration date (supplied or defaulted to the server date)
594	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
595	     */
596	    private LocalDate toBusinessDay(LocalDate date) {
597	        LocalDate result = date;
598	        while (isWeekend(result) || PUBLIC_HOLIDAYS.contains(result)) {
599	            result = result.plusDays(1);
600	        }
601	        return result;
602	    }
603	
604	    private boolean isWeekend(LocalDate date) {
605	        return switch (date.getDayOfWeek()) {
606	            case SATURDAY, SUNDAY -> true;
607	            default -> false;
608	        };
609	    }
610	
611	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
612	    @Override
613	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
614	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
615	        if (StringUtils.hasText(idempotencyKey)) {
616	            Integer existingId = idempotentCreates.get(idempotencyKey);
617	            if (existingId != null) {
618	                Owner existing = this.clinicService.findOwnerById(existingId);
619	                if (existing != null) {
620	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
621	                }
622	            }
623	        }
624	        applyAddressFields(ownerFieldsDto);
625	        validateRequiredFields(ownerFieldsDto);
626	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
627	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
628	        requireCityHasCapacity(ownerFieldsDto.getCity());
629	        String email = normalizeEmail(ownerFieldsDto.getEmail());
630	        HttpHeaders headers = new HttpHeaders();
631	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
632	        owner.setTelephone(telephone);
633	        owner.setEmail(email);
634	        owner.setDeleted(false);
635	        requireUniqueIdentity(owner);
636	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
637	        if (!sharesHousehold) {
638	            requireNoHouseholdDuplicate(owner);
639	        }
640	        requireRegistrationDateNotInFuture(owner.getRegistrationDate());
641	        LocalDate effectiveDate = owner.getRegistrationDate() != null
642	            ? owner.getRegistrationDate() : LocalDate.now();
643	        LocalDate registrationDate = toBusinessDay(effectiveDate);
644	        owner.setRegistrationDate(registrationDate);
645	        requireDailyLimitNotReached(registrationDate);
646	        owner.setBulkSignupWarning(isBulkSignup(registrationDate));
647	        Owner possibleDuplicate = sharesHousehold ? null : findPossibleDuplicate(owner);
648	        owner.setPossibleDuplicate(possibleDuplicate != null);
649	        owner.setPossibleDuplicateOf(possibleDuplicate == null ? null : possibleDuplicate.getId());
650	        this.clinicService.saveOwner(owner);
651	        if (StringUtils.hasText(idempotencyKey)) {
652	            idempotentCreates.put(idempotencyKey, owner.getId());
653	        }
654	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
655	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
656	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
657	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
658	        headers.setLocation(UriComponentsBuilder.newInstance()
659	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
660	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
661	    }
662	
663	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
664	    @Override
665	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
666	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
667	        if (currentOwner == null) {
668	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
669	        }
670	        currentOwner.setAddress(ownerFieldsDto.getAddress());
671	        currentOwner.setCity(ownerFieldsDto.getCity());
672	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
673	        currentOwner.setLastName(ownerFieldsDto.getLastName());
674	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
675	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
676	        this.clinicService.saveOwner(currentOwner);
677	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
678	    }
679	
680	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
681	    @Transactional
682	    @Override
683	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
684	        Owner owner = this.clinicService.findOwnerById(ownerId);
685	        if (owner == null) {
686	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
687	        }
688	        owner.setDeleted(true);
689	        this.clinicService.saveOwner(owner);
690	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
691	    }
692	
693	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
694	    @Override
695	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
696	        Owner owner = this.clinicService.findOwnerById(ownerId);
697	        if (owner == null) {
698	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
699	        }
700	        HttpHeaders headers = new HttpHeaders();
701	        Pet pet = petMapper.toPet(petFieldsDto);
702	        owner.setId(ownerId);
703	        pet.setOwner(owner);
704	        pet.getType().setName(null);
705	        this.clinicService.savePet(pet);
706	        PetDto petDto = petMapper.toPetDto(pet);
707	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
708	            .buildAndExpand(pet.getId()).toUri());
709	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
710	    }
711	
712	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
713	    @Override
714	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
715	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
716	        if (currentOwner != null) {
717	            Pet currentPet = this.clinicService.findPetById(petId);
718	            if (currentPet != null) {
719	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
720	                currentPet.setName(petFieldsDto.getName());
721	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
722	                this.clinicService.savePet(currentPet);
723	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
724	            }
725	        }
726	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
727	    }
728	
729	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
730	    @Override
731	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
732	        HttpHeaders headers = new HttpHeaders();
733	        Visit visit = visitMapper.toVisit(visitFieldsDto);
734	        Pet pet = new Pet();
735	        pet.setId(petId);
736	        visit.setPet(pet);
737	        this.clinicService.saveVisit(visit);
738	        VisitDto visitDto = visitMapper.toVisitDto(visit);
739	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
740	            .buildAndExpand(visit.getId()).toUri());
741	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
742	    }
743	
744	
745	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
746	    @Override
747	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
748	        Owner owner = this.clinicService.findOwnerById(ownerId);
749	        if (owner != null) {
750	            Pet pet = owner.getPet(petId);
751	            if (pet != null) {
752	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
753	            }
754	        }
755	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
756	    }
757	}
