18	
19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public interface OwnerMapper {
24	
25	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
26	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
27	    @Mapping(target = "displayName",
28	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
29	    @Mapping(target = "initials",
30	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
31	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
32	    @Mapping(target = "householdId", expression = "java(householdId(owner))")
33	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
34	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
35	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
36	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
37	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
38	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
39	    @Mapping(target = "locality", expression = "java(locality(owner))")
40	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
41	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
42	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
43	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
44	    OwnerDto toOwnerDto(Owner owner);
45	
46	    /**
47	     * Derives a link to the owner's own resource, formatted {@code /api/owners/<id>} where
48	     * {@code <id>} is the owner's id. Returns {@code null} when the owner has no id yet, so the
49	     * field is omitted from the response.
50	     *
51	     * @param owner the owner to derive the self link for
52	     * @return the {@code /api/owners/<id>} self link, or {@code null} when the owner has no id
53	     */
54	    default String selfLink(Owner owner) {
55	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
56	    }
57	
58	    /**
59	     * Derives an owner's salutation from its optional title and last name: {@code "<title> <lastName>"}
60	     * when a non-blank title is present, or just the last name when no title was supplied.
61	     *
62	     * @param owner the owner to derive the salutation for
63	     * @return the composed salutation
64	     */
65	    default String salutation(Owner owner) {
66	        String title = owner.getTitle();
67	        String lastName = owner.getLastName();
68	        if (title == null || title.isBlank()) {
69	            return lastName;
70	        }
71	        return title + " " + lastName;
72	    }
73	
74	    /**
75	     * Derives an owner's age band from its birth date, computed as the owner's age on its
76	     * {@link Owner#getRegistrationDate() registration date}: {@code "MINOR"} when under {@code 18},
77	     * {@code "ADULT"} when {@code 18} to {@code 64}, and {@code "SENIOR"} when {@code 65} or older.
78	     * Returns {@code null} when the owner has no birth date, so the field is omitted from the
79	     * response.
80	     *
81	     * @param owner the owner to derive the age band for
82	     * @return {@code "MINOR"}, {@code "ADULT"} or {@code "SENIOR"}, or {@code null} when no birth date
83	     *     is held
84	     */
85	    default String ageBand(Owner owner) {
86	        java.time.LocalDate birthDate = owner.getBirthDate();
87	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
88	        if (birthDate == null || registrationDate == null) {
89	            return null;
90	        }
91	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
92	        if (age < 18) {
93	            return "MINOR";
94	        }
95	        return age < 65 ? "ADULT" : "SENIOR";
96	    }
97	
98	    /**
99	     * Derives an owner's preferred contact channel: {@code "EMAIL"} when the owner has a non-blank
100	     * email, otherwise {@code "PHONE"}.
101	     *
102	     * @param owner the owner to derive the contact preference for
103	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
104	     */
105	    default String contactPreference(Owner owner) {
106	        String email = owner.getEmail();
107	        return (email != null && !email.isBlank()) ? "EMAIL" : "PHONE";
108	    }
109	
110	    /**
111	     * Known telephone country codes, matched longest-prefix first so {@code "61"} is preferred over
112	     * the {@code "1"} it starts with. Mirrors the country codes the create endpoint recognizes when
113	     * normalizing telephones into E.164 form.
114	     */
115	    java.util.List<String> TELEPHONE_COUNTRY_CODES = java.util.List.of("61", "1");
116	
117	    /**
118	     * Formats an owner's stored E.164 telephone for humans: the country code, a space, then the
119	     * national digits grouped in threes (e.g. {@code +61412345678} becomes {@code +61 412 345 678}).
120	     * The country code is taken as the longest recognized prefix (see
121	     * {@link #TELEPHONE_COUNTRY_CODES}), falling back to the leading digit; the raw
122	     * {@link Owner#getTelephone() telephone} stays in E.164 form. A {@code null} or non-E.164 value
123	     * is returned unchanged.
124	     *
125	     * @param owner the owner to format the telephone display for
126	     * @return the human-formatted telephone, or the raw value when it is not a {@code +}-prefixed
127	     *     digit string
128	     */
129	    default String telephoneDisplay(Owner owner) {
130	        String telephone = owner.getTelephone();
131	        if (telephone == null || !telephone.startsWith("+")) {
132	            return telephone;
133	        }
134	        String digits = telephone.substring(1);
135	        if (!digits.matches("[0-9]+")) {
136	            return telephone;
137	        }
138	        String countryCode = TELEPHONE_COUNTRY_CODES.stream()
139	            .filter(digits::startsWith)
140	            .max(java.util.Comparator.comparingInt(String::length))
141	            .orElseGet(() -> digits.substring(0, 1));
142	        String national = digits.substring(countryCode.length());
143	        StringBuilder sb = new StringBuilder("+").append(countryCode);
144	        for (int i = 0; i < national.length(); i += 3) {
145	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
146	        }
147	        return sb.toString();
148	    }
149	
150	    /**
151	     * Derives an owner's locality from the region-and-hash customer code: the {@code <REGION>}
152	     * segment (everything before the first {@code '-'}) of the owner's {@code customerCode}. Because
153	     * the customer code's region is itself derived from the postcode (falling back to the city), the
154	     * locality now moves with the identity rather than being computed independently. The result is
155	     * {@code "UNKNOWN"} when no customer code is present.
156	     *
157	     * @param owner the owner to derive the locality for
158	     * @return the region segment of the customer code, or {@code "UNKNOWN"}
159	     */
160	    default String locality(Owner owner) {
161	        String code = owner.getCustomerCode();
162	        if (code == null || code.isEmpty()) {
163	            return "UNKNOWN";
164	        }
165	        int dash = code.indexOf('-');
166	        return dash < 0 ? code : code.substring(0, dash);
167	    }
168	
169	    /**
170	     * Fixed region-to-timezone table mapping a canonical region to its IANA timezone name:
171	     * {@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}.
172	     */
173	    java.util.Map<String, String> REGION_TIMEZONES = java.util.Map.of(
174	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
175	
176	    /**
177	     * Derives an owner's IANA timezone name from its {@link #locality(Owner) locality/region} using
178	     * the fixed region-to-timezone table ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne},
179	     * {@code QLD->Australia/Brisbane}). Returns {@code null} when the region has no known timezone, so
180	     * the field is omitted from the response.
181	     *
182	     * @param owner the owner to derive the timezone for
183	     * @return the region's IANA timezone name, or {@code null} when the region has no known timezone
184	     */
185	    default String timezone(Owner owner) {
186	        return REGION_TIMEZONES.get(locality(owner));
187	    }
188	
189	    /**
190	     * Derives an owner's membership points. Starts at {@code 0}, plus {@code 2} when an email is
191	     * present (non-blank), plus {@code 1} when the owner's namesake count is {@code 0}, plus
192	     * {@code 2} for a household of {@code 3} or more members, plus {@code 3} for a tenure of more
193	     * than one elapsed fiscal year - the number of fiscal years between the owner's registration
194	     * date and the current server date (the fiscal year starts on 1 July). Because a newly created
195	     * owner registers on the current date, its tenure is zero, so a new owner never earns the tenure
196	     * points.
197	     *
198	     * @param owner the owner to derive the membership points for
199	     * @return the membership points, {@code 0} or more
200	     */
201	    default Integer membershipPoints(Owner owner) {
202	        int points = 0;
203	        String email = owner.getEmail();
204	        if (email != null && !email.isBlank()) {
205	            points += 2;
206	        }
207	        Integer namesakeCount = owner.getNamesakeCount();
208	        if (namesakeCount != null && namesakeCount == 0) {
209	            points += 1;
210	        }
211	        Integer householdMemberCount = owner.getHouseholdMemberCount();
212	        if (householdMemberCount != null && householdMemberCount >= 3) {
213	            points += 2;
214	        }
215	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
216	        long tenureFiscalYears = registrationDate == null ? 0
217	            : fiscalYearValue(java.time.LocalDate.now()) - fiscalYearValue(registrationDate);
218	        if (tenureFiscalYears > 1) {
219	            points += 3;
220	        }
221	        return points;
222	    }
223	
224	    /**
225	     * Derives an owner's numeric membership level from its {@link #membershipPoints(Owner) membership
226	     * points}: level {@code 1} for {@code 0}-{@code 1} points, {@code 2} for {@code 2}-{@code 3},
227	     * {@code 3} for {@code 4}-{@code 5}, and {@code 4} for {@code 6} or more.
228	     *
229	     * @param owner the owner to derive the membership level for
230	     * @return the membership level, between {@code 1} and {@code 4}
231	     */
232	    default Integer membershipLevel(Owner owner) {
233	        int points = membershipPoints(owner);
234	        if (points <= 1) {
235	            return 1;
236	        }
237	        if (points <= 3) {
238	            return 2;
239	        }
240	        if (points <= 5) {
241	            return 3;
242	        }
243	        return 4;
244	    }
245	
246	    /**
247	     * Derives an owner's membership number, formatted {@code <customerCode>-M<YY>} where
248	     * {@code <customerCode>} is the owner's region-and-hash customer code and {@code YY} is the last
249	     * two digits (zero-padded) of the owner's {@link #fiscalYear(Owner) fiscal year} - so the year
250	     * segment matches the returned {@code fiscalYear} (e.g. {@code NSW-1A2B3C4D-M27}).
251	     *
252	     * @param owner the owner to derive the membership number for
253	     * @return the formatted membership number
254	     */
255	    default String membershipNumber(Owner owner) {
256	        String yy = String.format("%02d", fiscalYearValue(owner.getRegistrationDate()) % 100);
257	        return owner.getCustomerCode() + "-M" + yy;
258	    }
259	
260	    /**
261	     * Derives an owner's fiscal year, formatted {@code FY<YY>} where {@code YY} is the last two
262	     * digits (zero-padded) of the fiscal year that the owner's business-day-adjusted registration
263	     * date falls in. The fiscal year starts on 1 July and is labelled by the calendar year in which
264	     * it ends, so a registration date on or after 1 July belongs to the next year's fiscal year
265	     * (e.g. {@code 2026-08-11 -> FY27}, {@code 2026-01-05 -> FY26}).
266	     *
267	     * @param owner the owner to derive the fiscal year for
268	     * @return the formatted fiscal year
269	     */
270	    default String fiscalYear(Owner owner) {
271	        return String.format("FY%02d", fiscalYearValue(owner.getRegistrationDate()) % 100);
272	    }
273	
274	    /**
275	     * Computes the fiscal year a date falls in as a full four-digit year. The fiscal year starts on
276	     * 1 July and is labelled by the calendar year in which it ends, so a date in July through
277	     * December belongs to the following calendar year's fiscal year and a date in January through
278	     * June belongs to its own calendar year's fiscal year.
279	     *
280	     * @param date the date to compute the fiscal year for
281	     * @return the fiscal year as a four-digit calendar year
282	     */
283	    private int fiscalYearValue(java.time.LocalDate date) {
284	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
285	    }
286	
287	    /**
288	     * Derives an owner's check digit: a single Luhn check digit ({@code 0}-{@code 9}) computed over
289	     * the digits contained in the owner's customer code. Non-digit characters in the customer code
290	     * are ignored.
291	     *
292	     * @param owner the owner to derive the check digit for
293	     * @return the Luhn check digit, between {@code 0} and {@code 9}
294	     */
295	    default Integer checkDigit(Owner owner) {
296	        String code = owner.getCustomerCode();
297	        int sum = 0;
298	        boolean dbl = true;
299	        for (int i = code.length() - 1; i >= 0; i--) {
300	            char c = code.charAt(i);
301	            if (c < '0' || c > '9') {
302	                continue;
303	            }
304	            int d = c - '0';
305	            if (dbl) {
306	                d *= 2;
307	                if (d > 9) {
308	                    d -= 9;
309	                }
310	            }
311	            sum += d;
312	            dbl = !dbl;
313	        }
314	        return (10 - (sum % 10)) % 10;
315	    }
316	
317	    /**
318	     * Derives an owner's household identifier: the first 12 hex characters of the SHA-256 digest
319	     * over {@code <normalizedLastName>|<postcode>}, where the last name is normalized
320	     * case-insensitively with collapsed whitespace and a missing postcode contributes the empty
321	     * string. Because it is derived deterministically from the last name and postcode, every owner
322	     * that shares those two fields receives the same value - including owners created via the
323	     * {@code sharesHousehold} flag, which by definition have a matching last name and postcode.
324	     *
325	     * @param owner the owner to derive the household identifier for
326	     * @return the 12 upper-case hex character household identifier, never blank
327	     */
328	    default String householdId(Owner owner) {
329	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
330	        String key = normalizeHouseholdField(owner.getLastName()) + '|' + postcode;
331	        try {
332	            byte[] digest = MessageDigest.getInstance("SHA-256")
333	                .digest(key.getBytes(StandardCharsets.UTF_8));
334	            StringBuilder sb = new StringBuilder(12);
335	            for (int i = 0; i < 6; i++) {
336	                sb.append(String.format("%02X", digest[i]));
337	            }
338	            return sb.toString();
339	        }
340	        catch (NoSuchAlgorithmException ex) {
341	            throw new IllegalStateException("SHA-256 not available", ex);
342	        }
343	    }
344	
345	    /**
346	     * Derives an owner's identity key, into which all duplicate detection is consolidated. The key
347	     * is {@code <normalizedTelephone>|<email or empty>|<householdId>}: the owner's (already E.164
348	     * normalized) telephone, its (already lower-cased) email or the empty string when none is held,
349	     * and its {@link #householdId(Owner) household id}. Two owners are duplicates only when their
350	     * whole identity keys are equal; because the telephone is part of the key, household members with
351	     * different telephones have different keys.
352	     *
353	     * @param owner the owner to derive the identity key for
354	     * @return the {@code telephone|email|householdId} identity key
355	     */
356	    default String identityKey(Owner owner) {
357	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
358	        String email = owner.getEmail() == null ? "" : owner.getEmail();
359	        return telephone + '|' + email + '|' + householdId(owner);
360	    }
361	
362	    /**
363	     * Collapses surrounding and internal whitespace and lower-cases a value so household fields can
364	     * be compared case-insensitively with collapsed whitespace. A {@code null} value normalizes to
365	     * the empty string. Mirrors the normalization used when enforcing the household rule on create.
366	     *
367	     * <p>Declared {@code private} so MapStruct does not treat it as an implicit String-to-String
368	     * conversion and apply it to unrelated String properties (last name, address, ...).
369	     */
370	    private String normalizeHouseholdField(String value) {
371	        if (value == null) {
372	            return "";
373	        }
374	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
375	    }
376	
377	    Owner toOwner(OwnerDto ownerDto);
378	
379	    @Mapping(target = "id", ignore = true)
380	    @Mapping(target = "pets", ignore = true)
381	    Owner toOwner(OwnerFieldsDto ownerDto);
382	
383	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
384	
385	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
386	
387	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
388	        OwnerPageDto ownerPageDto = new OwnerPageDto();
389	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
390	        ownerPageDto.setPage(ownerPage.getNumber());
391	        ownerPageDto.setSize(ownerPage.getSize());
392	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
393	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
394	        return ownerPageDto;
395	    }
396	}
