345	    /**
346	     * Look up the canonical region for a postcode by its range ({@code NSW 2000-2099},
347	     * {@code VIC 3000-3099}, {@code QLD 4000-4099}), returning {@code null} when the postcode is
348	     * absent, non-numeric or in no known range.
349	     */
350	    private String regionFromPostcode(String postcode) {
351	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
352	            return null;
353	        }
354	        int value = Integer.parseInt(postcode);
355	        if (value >= 2000 && value <= 2099) {
356	            return "NSW";
357	        }
358	        if (value >= 3000 && value <= 3099) {
359	            return "VIC";
360	        }
361	        if (value >= 4000 && value <= 4099) {
362	            return "QLD";
363	        }
364	        return null;
365	    }
