383	    /**
384	     * Compute the first 8 upper-case hex characters of the SHA-256 digest over the owner's
385	     * normalized telephone concatenated with the owner's last name.
386	     */
387	    private String hash8(Owner owner) {
388	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
389	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
390	        try {
391	            byte[] digest = MessageDigest.getInstance("SHA-256")
392	                .digest((telephone + lastName).getBytes(StandardCharsets.UTF_8));
393	            StringBuilder sb = new StringBuilder(8);
394	            for (int i = 0; i < 4; i++) {
395	                sb.append(String.format("%02X", digest[i]));
396	            }
397	            return sb.toString();
398	        }
399	        catch (NoSuchAlgorithmException ex) {
400	            throw new IllegalStateException("SHA-256 not available", ex);
401	        }
402	    }
